const payload = $input.first().json.body ?? $input.first().json;
const alerts = Array.isArray(payload.alerts) ? payload.alerts : [];
const first = alerts[0] ?? {};
const labels = first.labels ?? {};
const annotations = first.annotations ?? {};
const status = payload.status ?? first.status ?? 'unknown';
const alertname = labels.alertname ?? 'UnknownAlert';
const severity = labels.severity ?? 'unknown';
const lines = alerts.map((a) => {
  const l = a.labels ?? {};
  const an = a.annotations ?? {};
  return `- ${l.alertname ?? 'Unknown'} [${l.severity ?? 'n/a'}] ${a.status ?? status}: ${an.summary ?? an.description ?? ''}`;
});
const alertSummary = `Status: ${status}\nAlert count: ${alerts.length}\n${lines.join('\n')}`;
return [{ json: { status, alertname, severity, count: alerts.length, alertSummary } }];
